SELECT groupCd, groupNm, serviceCd, serviceNm, '' AS `inOut` FROM ( SELECT LEFT(A.SERVICECD, 1) AS groupCd, SERVICENM_LV1 AS groupNm, LEFT(A.SERVICECD, 3) AS serviceCd, SERVICENM_LV2 AS serviceNm, '' AS `inOut`, SORT FROM UI_SERVICE A LEFT JOIN UI_ADMIN_SERVICE B ON LEFT(A.SERVICECD, 3) = B.SERVICECD WHERE B.ADMIN_ID = #{adminId} AND A.USE_YN='Y' UNION SELECT LEFT(SERVICECD, 1) AS groupCd, SERVICENM_LV1 AS groupNm, LEFT(SERVICECD, 3) AS serviceCd, SERVICENM_LV2 AS serviceNm, '' AS `inOut`, SORT FROM UI_SERVICE WHERE 0 =(SELECT COUNT(*) AS CNT FROM UI_ADMIN_SERVICE WHERE ADMIN_ID=#{adminId}) AND USE_YN='Y'
UNION SELECT LEFT(A.SERVICECD, 1) AS groupCd, SERVICENM_LV1 AS groupNm, LEFT(A.SERVICECD, 4) AS serviceCd, SERVICENM_LV3 AS serviceNm, '' AS `inOut`, SORT FROM UI_SERVICE A LEFT JOIN UI_ADMIN_SERVICE B ON LEFT(A.SERVICECD, 4) = B.SERVICECD WHERE B.ADMIN_ID = #{adminId} AND A.USE_YN='Y' AND ( LEFT(A.SERVICECD, 3) = 'EMM' OR A.SERVICECD IN ('UWSH', 'UWSM', 'UWSL','CMLS','CMLE','SNVU')) UNION SELECT LEFT(SERVICECD, 1) AS groupCd, SERVICENM_LV1 AS groupNm, LEFT(SERVICECD, 4) AS serviceCd, SERVICENM_LV3 AS serviceNm, '' AS `inOut`, SORT FROM UI_SERVICE WHERE 0 =(SELECT COUNT(*) AS CNT FROM UI_ADMIN_SERVICE WHERE ADMIN_ID=#{adminId}) AND USE_YN='Y' AND ( LEFT(SERVICECD, 3) = 'EMM' OR SERVICECD IN ('UWSH', 'UWSM', 'UWSL','CMLS','CMLE','SNVU') )
UNION SELECT LEFT(A.SERVICECD, 1) AS groupCd, SERVICENM_LV1 AS groupNm, CONCAT(LEFT(A.SERVICECD, 4),'X') AS serviceCd, CONCAT('[ ',SERVICENM_LV2,'_',SERVICENM_LV3,CASE WHEN (SELECT COUNT(*) AS CNT FROM UI_SERVICE WHERE SERVICECD = 'EMMA' AND SERVICENM_LV3 REGEXP '[가-힣]') > 0 THEN ' 제외 ]' ELSE ' except ]' END) AS serviceNm, '' AS `inOut`, (SELECT MAX(SORT)+1 FROM UI_SERVICE WHERE LEFT(SERVICECD, 3) = 'EMM') AS SORT FROM UI_SERVICE A LEFT JOIN UI_ADMIN_SERVICE B ON LEFT(A.SERVICECD, 5) = B.SERVICECD WHERE B.ADMIN_ID = #{adminId} AND A.USE_YN='Y' AND A.SERVICECD = 'EMMA' UNION SELECT LEFT(SERVICECD, 1) AS groupCd, SERVICENM_LV1 AS groupNm, CONCAT(LEFT(SERVICECD, 4),'X') AS serviceCd, CONCAT('[ ',SERVICENM_LV2,'_',SERVICENM_LV3,CASE WHEN (SELECT COUNT(*) AS CNT FROM UI_SERVICE WHERE SERVICECD = 'EMMA' AND SERVICENM_LV3 REGEXP '[가-힣]') > 0 THEN ' 제외 ]' ELSE ' except ]' END) AS serviceNm, '' AS `inOut`, (SELECT MAX(SORT)+1 FROM UI_SERVICE WHERE LEFT(SERVICECD, 3) = 'EMM' ) AS SORT FROM UI_SERVICE WHERE 0 =(SELECT COUNT(*) AS CNT FROM UI_ADMIN_SERVICE WHERE ADMIN_ID=#{adminId}) AND USE_YN='Y' AND SERVICECD = 'EMMA'
) as rs
WHERE groupCd = #{svc1}
GROUP BY groupCd, groupNm, serviceCd, serviceNm ORDER BY MAX(SORT)

SELECT  CONCAT(SERVICENM_LV1, ' > ', SERVICENM_LV2, ' > ', SERVICENM_LV3) AS serviceNm
FROM	UI_SERVICE
WHERE	SERVICECD = #{serviceCd}

